// npm run heroes:sync -- after merging main (or another Beatbox Heroes branch) into yours, or whenever git reports conflicts in the generated 3D build.
//
// The Beatbox Heroes 3D build (beatbox_heroes/park3d.bundle.js, r3/entry.js, r3/p3-*.js, and the ?v=<hash> stamps in its five pages) is generated by `node build.js`
// and committed (Cloudflare Pages runs no build). Content-hashed chunk names mean two branches that both changed park3d/ ALWAYS conflict there, and the right answer
// is never to pick a side: it is to rebuild from the merged sources. This does exactly that:
//   1. stops (touching nothing) when a hand-written file under beatbox_heroes/ still has a conflict: resolve those first
//   2. drops the conflicted generated files from the index (the build recreates them)
//   3. resolves conflicts in the five pages that are only hash stamps (a real hand edit conflict is left for you and reported)
//   4. runs node build.js (regenerates the mirror, removes stale chunks, restamps the pages)
//   5. stages exactly the generated files and the stamped pages, so `git commit` finishes the merge
// Usage: node tools/beatbox_heroes/sync_build.mjs [--no-stage]
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

export const GENERATED = /^beatbox_heroes\/(park3d\.bundle\.js|r3\/entry\.js|r3\/p3-[\w.-]+\.js)$/;
export const PAGES = ['index.html', 'park3d.html', 'flat3d.html', 'minigames3d.html', 'world3d.html'].map((f) => 'beatbox_heroes/' + f);
const STAMP = /((?:r3\/entry\.js|park3d\.bundle\.js)\?v=)[0-9a-zA-Z]+/g;

/** Resolve conflict hunks whose two sides differ only by a build hash stamp (take ours: the build restamps it anyway).
 *  Returns { text, left } where left = number of hunks that differ in anything else (those stay, markers included). */
export function resolveStampConflicts(text) {
  let left = 0;
  const out = text.replace(/^<<<<<<< [^\n]*\n([\s\S]*?)^=======\n([\s\S]*?)^>>>>>>> [^\n]*\n/gm, (hunk, ours, theirs) => {
    if (ours.replace(STAMP, '$1X') === theirs.replace(STAMP, '$1X')) return ours;
    left++;
    return hunk;
  });
  return { text: out, left };
}

function main() {
  const REPO = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
  const git = (...a) => execFileSync('git', a, { cwd: REPO, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  const stage = !process.argv.includes('--no-stage');
  const say = (m) => console.log('heroes:sync  ' + m);
  const unmerged = () => git('diff', '--name-only', '--diff-filter=U').split('\n').filter(Boolean);

  // 1. a conflict in anything hand-written under beatbox_heroes/ is yours to resolve first
  const blocking = unmerged().filter((f) => f.startsWith('beatbox_heroes/') && !GENERATED.test(f) && !PAGES.includes(f));
  if (blocking.length) {
    console.error('heroes:sync  resolve these hand-written conflicts first, then run it again:\n  ' + blocking.join('\n  '));
    process.exit(1);
  }

  // 2. conflicted generated files: forget them, the build recreates them from the merged sources
  const gen = unmerged().filter((f) => GENERATED.test(f));
  for (const f of gen) { try { git('rm', '-q', '--cached', '--', f); } catch (e) { /* already gone from the index */ } }
  if (gen.length) say(gen.length + ' conflicted generated file(s) dropped from the index (rebuilt below)');

  // 3. pages: a conflict that is only a hash stamp is resolved, anything else stays
  let pagesLeft = 0;
  for (const f of unmerged().filter((x) => PAGES.includes(x))) {
    const file = path.join(REPO, f), r = resolveStampConflicts(fs.readFileSync(file, 'utf8'));
    fs.writeFileSync(file, r.text);
    if (r.left) { pagesLeft += r.left; console.error('heroes:sync  ' + f + ': ' + r.left + ' conflict(s) that are not just a hash stamp, resolve them by hand'); }
    else if (stage) git('add', '--', f);
  }
  if (pagesLeft) process.exit(1);

  // 4. rebuild everything from the merged sources
  say('node build.js ...');
  execFileSync(process.execPath, ['build.js'], { cwd: REPO, stdio: 'pipe' });

  // 5. stage exactly the generated files and the stamped pages (never a hand-written file you are still editing)
  if (!stage) { say('built (not staged: --no-stage)'); return; }
  const touched = [...new Set(git('ls-files', '-m', '-d', '-o', '--exclude-standard', '--', 'beatbox_heroes').split('\n'))].filter((f) => GENERATED.test(f) || PAGES.includes(f));
  const known = new Set(git('ls-files', '--', 'beatbox_heroes').split('\n'));
  const tracked = touched.filter((f) => known.has(f)), fresh = touched.filter((f) => !known.has(f));
  if (touched.length) git('add', '-A', '--', ...touched);
  say(touched.length ? 'staged ' + touched.length + ' file(s) (' + tracked.length + ' changed or removed, ' + fresh.length + ' new)' : 'the committed build already matches the sources, nothing to stage');
  const rest = unmerged();
  if (rest.length) { console.error('heroes:sync  still unmerged (not Beatbox Heroes):\n  ' + rest.join('\n  ')); process.exit(1); }
  say('done. Commit to finish the merge.');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
